1	import { Client, type ClientChannel, type SFTPWrapper } from "ssh2";
2	import { connectionTarget, serverRootPassword } from "../lib/sftp";
3	import { decryptSecret } from "../lib/crypto-box";
4	
5	/**
6	 * SECURE real cross-provider migration engine (gated behind ENABLE_REAL_MIGRATION).
7	 *
8	 * This replaces the earlier, REVERTED implementation that built shell command
9	 * strings out of customer-supplied DB names / users / paths and ran them as root
10	 * over SSH — a shell-injection / RCE hole. This version is hardened on two axes:
11	 *
12	 *   1. STRICT ALLOWLIST VALIDATION. Every non-secret input (source host, port,
13	 *      user, file paths, DB engine/name/user) must match a shell-inert allowlist
14	 *      regex or the migration FAILS. We reject — never sanitize. The permitted
15	 *      charsets contain no shell metacharacters, so even though validated values
16	 *      are interpolated into command strings, there is no injection surface.
17	 *
18	 *   2. SECRETS NEVER TOUCH A COMMAND STRING. The source SSH password is written
19	 *      to a 0600 file on the target over the SFTP channel (bytes, not a shell
20	 *      arg) and consumed with `sshpass -f`. Source DB passwords are written into
21	 *      a defaults-extra-file (MySQL) / .pgpass (Postgres) on the source by
22	 *      streaming the file body through the command's STDIN — again never as an
23	 *      argv token. Command strings reference only file PATHS.
24	 *
25	 * Scope (v1): files are pulled directly (rsync) into a staging dir on the target;
26	 * databases are DUMPED into that staging dir (no auto-import — we don't assume the
27	 * target's DB layout/users, which would be fragile and risky). The customer is
28	 * told exactly where everything landed and how to finish. All work is confined to
29	 * a per-migration work dir; system paths are never overwritten.
30	 *
31	 * Every secret is used in-memory only and scrubbed from disk in a finally block.
32	 */
33	
34	type ReportFn = (progress: number, step: string, line: string) => Promise<void>;
35	
36	type MigrationRow = {
37	  id: string;
38	  sourceHost: string;
39	  sourcePort: number;
40	  sourceUser: string;
41	  sourcePasswordEnc: string | null;
42	};
43	
44	type TargetServer = {
45	  id: string;
46	  rootPassword: string | null;
47	  rootPasswordEnc?: string | null;
48	  sshPort: number | null;
49	  dedicatedIp?: { address: string } | null;
50	};
51	
52	type DbItem = { engine: string; name: string; user: string; passEnc?: string };
53	type Items = { paths?: string[]; databases?: DbItem[] };
54	
55	export type RealMigrationInput = {
56	  migration: MigrationRow;
57	  target: TargetServer | null;
58	  items: Items;
59	  report: ReportFn;
60	};
61	
62	// ---- Timeouts -------------------------------------------------------------
63	const CONNECT_TIMEOUT_MS = 20_000;
64	const SETUP_TIMEOUT_MS = 60_000; // installs, mkdir, small writes
65	const TRANSFER_TIMEOUT_MS = Number(process.env.MIGRATE_EXEC_TIMEOUT_MS ?? 45 * 60_000); // rsync/dump
66	
67	// ---- Strict allowlist validators (throw on any violation) -----------------
68	// Charsets below are deliberately shell-inert: no quotes, spaces, metachars, or
69	// newlines. Validated values are therefore safe to interpolate into a command.
70	const HOSTNAME_RE = /^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$/;
71	const IPV4_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;
72	const IPV6_RE = /^[0-9A-Fa-f:]{2,45}$/;
73	const USER_RE = /^[a-z_][a-z0-9_-]{0,31}$/;
74	const IDENT_RE = /^[A-Za-z0-9_]{1,64}$/; // DB name / DB user
75	const PATH_RE = /^\/[A-Za-z0-9._/-]{0,255}$/; // absolute path, safe charset
76	
77	function assert(cond: unknown, msg: string): asserts cond {
78	  if (!cond) throw new Error(msg);
79	}
80	
81	function validHost(h: string): boolean {
82	  return typeof h === "string" && (HOSTNAME_RE.test(h) || IPV4_RE.test(h) || IPV6_RE.test(h));
83	}
84	
85	function validPath(p: string): boolean {
86	  return typeof p === "string" && PATH_RE.test(p) && !p.includes("..") && !p.includes("//");
87	}
88	
89	/** dirname of a validated absolute path (both inputs/outputs are shell-inert). */
90	function parentDir(p: string): string {
91	  const i = p.lastIndexOf("/");
92	  return i <= 0 ? "/" : p.slice(0, i);
93	}
94	
95	// ---- SSH plumbing ---------------------------------------------------------
96	function execRemote(
97	  conn: Client,
98	  cmd: string,
99	  timeoutMs: number
100	): Promise<{ code: number; stdout: string; stderr: string }> {
101	  return new Promise((resolve, reject) => {
102	    conn.exec(cmd, (err, stream: ClientChannel) => {
103	      if (err) return reject(err);
104	      let stdout = "";
105	      let stderr = "";
106	      const timer = setTimeout(() => {
107	        try {
108	          stream.close();
109	        } catch {
110	          /* ignore */
111	        }
112	        reject(new Error("remote command timed out"));
113	      }, timeoutMs);
114	      stream
115	        .on("close", (code: number) => {
116	          clearTimeout(timer);
117	          resolve({ code: code ?? 0, stdout, stderr });
118	        })
119	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
120	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
121	    });
122	  });
123	}
124	
125	/**
126	 * Run a remote command and stream `input` into its STDIN. Used to write a secret
127	 * into a file on the far side (`cat > file`) without the secret ever appearing as
128	 * a command-line argument.
129	 */
130	function execRemoteInput(
131	  conn: Client,
132	  cmd: string,
133	  input: string,
134	  timeoutMs: number
135	): Promise<{ code: number; stdout: string; stderr: string }> {
136	  return new Promise((resolve, reject) => {
137	    conn.exec(cmd, (err, stream: ClientChannel) => {
138	      if (err) return reject(err);
139	      let stdout = "";
140	      let stderr = "";
141	      const timer = setTimeout(() => {
142	        try {
143	          stream.close();
144	        } catch {
145	          /* ignore */
146	        }
147	        reject(new Error("remote command timed out"));
148	      }, timeoutMs);
149	      stream
150	        .on("close", (code: number) => {
151	          clearTimeout(timer);
152	          resolve({ code: code ?? 0, stdout, stderr });
153	        })
154	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
155	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
156	      stream.end(input);
157	    });
158	  });
159	}
160	
161	/** Write bytes to a remote file over SFTP with a fixed 0600 mode (no shell). */
162	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
163	  return new Promise((resolve, reject) => {
164	    const ws = sftp.createWriteStream(path, { mode: 0o600 });
165	    ws.on("close", () => resolve());
166	    ws.on("error", (e: Error) => reject(e));
167	    ws.end(Buffer.from(content, "utf8"));
168	  });
169	}
170	
171	function connectTarget(server: TargetServer): Promise<{ conn: Client; sftp: SFTPWrapper }> {
172	  return new Promise((resolve, reject) => {
173	    const target = connectionTarget(server as any);
174	    if (!target) return reject(new Error("target server is not reachable yet — connection details are pending"));
175	    const password = serverRootPassword(server);
176	    if (!password) return reject(new Error("target server has no root password on record"));
177	    const conn = new Client();
178	    conn.on("ready", () => {
179	      conn.sftp((err, sftp) => {
180	        if (err) return reject(err);
181	        resolve({ conn, sftp });
182	      });
183	    });
184	    conn.on("error", (e) => reject(e instanceof Error ? e : new Error(String(e))));
185	    conn.connect({
186	      host: target.host,
187	      port: target.port,
188	      username: "root",
189	      password,
190	      readyTimeout: CONNECT_TIMEOUT_MS,
191	    });
192	  });
193	}
194	
195	// ---------------------------------------------------------------------------
196	
197	/**
198	 * Perform a real migration. Throws on any fatal error (migrate.ts records it as
199	 * FAILED and scrubs stored secrets). Validated inputs are shell-inert; secrets
200	 * flow only through SFTP writes and command STDIN.
201	 */
202	export async function runRealMigration(input: RealMigrationInput): Promise<void> {
203	  const { migration, target, items, report } = input;
204	  assert(target, "target server row not found");
205	
206	  // ---- 1. Validate EVERY non-secret input up front (fail closed) ----------
207	  const host = migration.sourceHost;
208	  const port = migration.sourcePort;
209	  const user = migration.sourceUser;
210	  assert(validHost(host), "source host is not a valid hostname or IP address");
211	  assert(Number.isInteger(port) && port >= 1 && port <= 65535, "source SSH port is out of range");
212	  assert(USER_RE.test(user), "source username contains unsupported characters");
213	
214	  const paths = (items.paths ?? []).map((p) => p.trim()).filter(Boolean);
215	  for (const p of paths) assert(validPath(p), `unsupported file path: ${p}`);
216	
217	  const databases = items.databases ?? [];
218	  for (const d of databases) {
219	    assert(d.engine === "mysql" || d.engine === "postgres", `unsupported database engine: ${d.engine}`);
220	    assert(IDENT_RE.test(d.name), `unsupported database name: ${d.name}`);
221	    assert(IDENT_RE.test(d.user), `unsupported database user: ${d.user}`);
222	  }
223	
224	  assert(paths.length || databases.length, "nothing selected to migrate");
225	
226	  // ---- 2. Decrypt secrets IN MEMORY ONLY ----------------------------------
227	  const sshPass = decryptSecret(migration.sourcePasswordEnc);
228	  assert(sshPass, "source SSH password is missing or could not be decrypted");
229	
230	  // ---- 3. Connect to the TARGET (our own server) --------------------------
231	  await report(10, "Connecting…", `Connecting to your Nxeon server to prepare the transfer.`);
232	  const { conn, sftp } = await connectTarget(target!);
233	
234	  // Per-migration work dir on the target (migration.id is a cuid — alphanumeric).
235	  const work = `/root/nxeon-migrations/${migration.id}`;
236	  const passFile = `${work}/ssh.pass`;
237	  const knownHosts = `${work}/known_hosts`;
238	  // SSH options for every source connection: force password auth, TOFU host key.
239	  const sshOpts =
240	    `-p ${port} -o StrictHostKeyChecking=accept-new -o UserKnownHostsFile=${knownHosts} ` +
241	    `-o ConnectTimeout=25 -o PreferredAuthentications=password -o PubkeyAuthentication=no`;
242	  const srcSpec = `${user}@${host}`;
243	
244	  try {
245	    // ---- 4. Prepare the target: tools + work dir + secret file -------------
246	    await report(14, "Preparing…", "Ensuring transfer tools (rsync, sshpass) are present on the target.");
247	    // Fixed command — no user input. Best-effort across apt/dnf/yum; ignore if present.
248	    await execRemote(
249	      conn,
250	      `command -v rsync >/dev/null 2>&1 && command -v sshpass >/dev/null 2>&1 || ` +
251	        `{ (apt-get update -y && apt-get install -y rsync sshpass) || (dnf install -y rsync sshpass) || (yum install -y rsync sshpass); }`,
252	      SETUP_TIMEOUT_MS
253	    );
254	    const tools = await execRemote(conn, `command -v rsync && command -v sshpass`, SETUP_TIMEOUT_MS);
255	    assert(tools.code === 0, "could not install rsync/sshpass on the target server");
256	
257	    await execRemote(
258	      conn,
259	      `mkdir -p ${work}/files ${work}/dumps && chmod 700 ${work} && touch ${knownHosts} && chmod 600 ${knownHosts}`,
260	      SETUP_TIMEOUT_MS
261	    );
262	
263	    // Write the source SSH password to a 0600 file over SFTP (never a shell arg).
264	    await sftpWrite(sftp, passFile, sshPass);
265	
266	    // ---- 5. Files: rsync-pull each path into the staging dir ---------------
267	    if (paths.length) {
268	      await report(30, "Copying files…", `Copying ${paths.length} path(s) from ${srcSpec}.`);
269	      let idx = 0;
270	      for (const p of paths) {
271	        idx++;
272	        const destParent = `${work}/files${parentDir(p)}`;
273	        await execRemote(conn, `mkdir -p ${destParent}`, SETUP_TIMEOUT_MS);
274	        const pct = 30 + Math.round((idx / paths.length) * 30); // 30 → 60
275	        await report(pct, "Copying files…", `  rsync ${p}`);
276	        const r = await execRemote(
277	          conn,
278	          `sshpass -f ${passFile} rsync -az --numeric-ids --timeout=1200 -e 'ssh ${sshOpts}' ${srcSpec}:${p} ${destParent}/`,
279	          TRANSFER_TIMEOUT_MS
280	        );
281	        if (r.code !== 0) {
282	          const tail = (r.stderr || r.stdout || "").split("\n").slice(-3).join(" ").slice(0, 300);
283	          throw new Error(`file copy failed for ${p}: ${tail || `rsync exit ${r.code}`}`);
284	        }
285	      }
286	    }
287	
288	    // ---- 6. Databases: dump each into the staging dir ---------------------
289	    if (databases.length) {
290	      await report(65, "Dumping databases…", `Dumping ${databases.length} database(s) from the source.`);
291	      let idx = 0;
292	      for (const d of databases) {
293	        idx++;
294	        const dbPass = decryptSecret(d.passEnc);
295	        assert(dbPass, `database password for "${d.name}" is missing or could not be decrypted`);
296	        const pct = 65 + Math.round((idx / databases.length) * 25); // 65 → 90
297	        await report(pct, "Dumping databases…", `  ${d.engine === "postgres" ? "pg_dump" : "mysqldump"} ${d.name}`);
298	
299	        if (d.engine === "mysql") {
300	          const srcCnf = `.nxmig-${migration.id}-${idx}.cnf`;
301	          const dumpFile = `${work}/dumps/mysql-${d.name}.sql`;
302	          // Write a defaults-extra-file on the SOURCE via STDIN (password never an argv token).
303	          const cnfBody = `[client]\nuser=${d.user}\npassword=${dbPass}\nhost=127.0.0.1\n`;
304	          const w = await execRemoteInput(
305	            conn,
306	            `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} 'umask 077; cat > ${srcCnf}'`,
307	            cnfBody,
308	            SETUP_TIMEOUT_MS
309	          );
310	          assert(w.code === 0, `could not stage MySQL credentials for "${d.name}"`);
311	          // Dump on source, stream to a file on the target. mysqldump reads the
312	          // password from the cnf file — no secret on the command line.
313	          const r = await execRemote(
314	            conn,
315	            `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} ` +
316	              `'mysqldump --defaults-extra-file=${srcCnf} --single-transaction --routines --triggers --databases ${d.name}' > ${dumpFile}`,
317	            TRANSFER_TIMEOUT_MS
318	          );
319	          // Always remove the staged credentials file on the source.
320	          await execRemote(conn, `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} 'rm -f ${srcCnf}'`, SETUP_TIMEOUT_MS).catch(() => {});
321	          if (r.code !== 0) {
322	            const tail = (r.stderr || "").split("\n").slice(-3).join(" ").slice(0, 300);
323	            throw new Error(`mysqldump failed for ${d.name}: ${tail || `exit ${r.code}`}`);
324	          }
325	        } else {
326	          const srcPgpass = `.nxmig-${migration.id}-${idx}.pgpass`;
327	          const dumpFile = `${work}/dumps/postgres-${d.name}.sql`;
328	          // .pgpass line: host:port:database:username:password (host/port/db/user validated).
329	          const pgpassBody = `127.0.0.1:*:${d.name}:${d.user}:${dbPass}\n`;
330	          const w = await execRemoteInput(
331	            conn,
332	            `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} 'umask 077; cat > ${srcPgpass}'`,
333	            pgpassBody,
334	            SETUP_TIMEOUT_MS
335	          );
336	          assert(w.code === 0, `could not stage Postgres credentials for "${d.name}"`);
337	          // PGPASSFILE points pg_dump at the file — its value is a validated path,
338	          // not a secret. The password lives only inside the file.
339	          const r = await execRemote(
340	            conn,
341	            `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} ` +
342	              `'PGPASSFILE=$HOME/${srcPgpass} pg_dump -h 127.0.0.1 -U ${d.user} ${d.name}' > ${dumpFile}`,
343	            TRANSFER_TIMEOUT_MS
344	          );
345	          await execRemote(conn, `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} 'rm -f ${srcPgpass}'`, SETUP_TIMEOUT_MS).catch(() => {});
346	          if (r.code !== 0) {
347	            const tail = (r.stderr || "").split("\n").slice(-3).join(" ").slice(0, 300);
348	            throw new Error(`pg_dump failed for ${d.name}: ${tail || `exit ${r.code}`}`);
349	          }
350	        }
351	      }
352	    }
353	
354	    await report(94, "Finalising…", `Transfer complete. Files staged under ${work}/files, database dumps under ${work}/dumps.`);
355	  } finally {
356	    // ---- 7. Scrub the SSH password file from the target, always -----------
357	    await execRemote(conn, `shred -u ${passFile} 2>/dev/null || rm -f ${passFile}`, SETUP_TIMEOUT_MS).catch(() => {});
358	    try {
359	      conn.end();
360	    } catch {
361	      /* best-effort */
362	    }
363	  }
364	}
365	
366	/** Where migrated data lands on the target, for the completion notice. */
367	export function migrationWorkDir(migrationId: string): string {
368	  return `/root/nxeon-migrations/${migration_id_safe(migrationId)}`;
369	}
370	
371	function migration_id_safe(id: string): string {
372	  return /^[A-Za-z0-9_-]{1,64}$/.test(id) ? id : "invalid";
373	}
