240	// ---- SSH plumbing (same shape as migrate-real.ts) -------------------------
241	function execRemote(
242	  conn: Client,
243	  cmd: string,
244	  timeoutMs: number
245	): Promise<{ code: number; stdout: string; stderr: string }> {
246	  return new Promise((resolve, reject) => {
247	    conn.exec(cmd, (err, stream: ClientChannel) => {
248	      if (err) return reject(err);
249	      let stdout = "";
250	      let stderr = "";
251	      const timer = setTimeout(() => {
252	        try {
253	          stream.close();
254	        } catch {
255	          /* ignore */
256	        }
257	        reject(new Error("remote command timed out"));
258	      }, timeoutMs);
259	      stream
260	        .on("close", (code: number) => {
261	          clearTimeout(timer);
262	          resolve({ code: code ?? 0, stdout, stderr });
263	        })
264	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
265	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
266	    });
267	  });
268	}
269	
270	/** Run a command, streaming `input` into its STDIN (secret goes here, never argv). */
271	function execRemoteInput(
272	  conn: Client,
273	  cmd: string,
274	  input: string,
275	  timeoutMs: number
276	): Promise<{ code: number; stdout: string; stderr: string }> {
277	  return new Promise((resolve, reject) => {
278	    conn.exec(cmd, (err, stream: ClientChannel) => {
279	      if (err) return reject(err);
280	      let stdout = "";
281	      let stderr = "";
282	      const timer = setTimeout(() => {
283	        try {
284	          stream.close();
285	        } catch {
286	          /* ignore */
287	        }
288	        reject(new Error("remote command timed out"));
289	      }, timeoutMs);
290	      stream
291	        .on("close", (code: number) => {
292	          clearTimeout(timer);
293	          resolve({ code: code ?? 0, stdout, stderr });
294	        })
295	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
296	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
297	      stream.end(input);
298	    });
299	  });
300	}
