302	function connectSource(input: DetectInput): Promise<Client> {
303	  return new Promise((resolve, reject) => {
304	    const conn = new Client();
305	    conn.on("ready", () => resolve(conn));
306	    conn.on("error", (e) => reject(e instanceof Error ? e : new Error(String(e))));
307	    conn.connect({
308	      host: input.host,
309	      port: input.port,
310	      username: input.user,
311	      password: input.password,
312	      readyTimeout: CONNECT_TIMEOUT_MS,
313	      // Password-only: never offer a local key to the untrusted source host.
314	      tryKeyboard: false,
315	    });
316	  });
317	}
