467	// ---- Public entrypoint ----------------------------------------------------
468	/**
469	 * SSH into the source (read-only) and return a structured inventory. Throws only
470	 * on a fatal connection/auth failure; a source that is reachable but has (say) no
471	 * readable DB creds still returns a useful partial result with notes.
472	 */
473	export async function detectSource(input: DetectInput): Promise<ScanResult> {
474	  assert(validHost(input.host), "source host is not a valid hostname or IP address");
475	  assert(Number.isInteger(input.port) && input.port >= 1 && input.port <= 65535, "source SSH port is out of range");
476	  assert(USER_RE.test(input.user), "source SSH username contains unsupported characters");
477	  assert(input.password && input.password.length > 0, "source SSH password is required");
478	
479	  const notes: string[] = [];
480	  const webRoots: DetectedWebRoot[] = [];
481	  const homes: DetectedHome[] = [];
482	  const databases: DetectedDatabase[] = [];
483	  const engines: DetectedEngine[] = [];
484	  const rawAppDirs: DetectedAppDir[] = [];
485	  const containers: DetectedContainer[] = [];
486	  const ports: DetectedPort[] = [];
487	  const services: DetectedService[] = [];
488	  const seenPort = new Set<string>();
489	
490	  const conn = await connectSource(input);
491	  try {
492	    // ---- 1. Filesystem + engine probe (fixed, input-free, read-only) ------
493	    const scan = await execRemote(conn, SCAN_SCRIPT, SCAN_TIMEOUT_MS);
494	    const engineState: Record<"mysql" | "postgres", { present: boolean; listening: boolean }> = {
495	      mysql: { present: false, listening: false },
496	      postgres: { present: false, listening: false },
497	    };
498	
499	    for (const raw of scan.stdout.split("\n")) {
500	      const line = raw.replace(/\r$/, "");
501	      if (!line) continue;
502	      const parts = line.split("\t");
503	      if (parts[0] === "WEB" && parts.length >= 4) {
504	        const appType = parts[1] as WebAppType;
505	        const sizeLabel = parts[2] || "?";
506	        const path = normalizeRemotePath(parts[3]);
507	        if (!validPath(path)) continue;
508	        if (webRoots.some((w) => w.path === path)) continue;
509	        webRoots.push({
510	          path,
511	          sizeLabel,
512	          appType: (["wordpress", "laravel", "django", "node", "php"] as WebAppType[]).includes(appType)
513	            ? appType
514	            : "unknown",
515	        });
516	      } else if (parts[0] === "HOME" && parts.length >= 3) {
517	        const sizeLabel = parts[1] || "?";
518	        const path = normalizeRemotePath(parts[2]);
519	        if (!validPath(path)) continue;
520	        if (homes.some((h) => h.path === path)) continue;
521	        homes.push({ path, sizeLabel });
522	      } else if (parts[0] === "ENGINE" && parts.length >= 4) {
523	        const eng = parts[1] === "postgres" ? "postgres" : "mysql";
524	        engineState[eng] = { present: parts[2] === "1", listening: parts[3] === "1" };
525	      } else if (parts[0] === "APPDIR" && parts.length >= 5) {
526	        const sizeLabel = parts[3] || "?";
527	        const path = normalizeRemotePath(parts[4]);
528	        if (!validPath(path)) continue; // candidate for TRANSFER — must pass the strict allowlist
529	        rawAppDirs.push({
530	          path,
531	          sizeLabel,
532	          runtime: mapRuntime(parts[1]),
533	          signature: mapSignature(parts[2]),
534	        });
535	      } else if (parts[0] === "DOCKER") {
536	        // Line body is "name|image|ports|mounts" (never contains a tab, so parts[1] holds it whole).
537	        if (containers.length >= MAX_CONTAINERS) continue;
538	        const seg = (parts.slice(1).join("\t")).split("|");
539	        const name = cleanText(seg[0] ?? "", 128);
540	        if (!CONTNAME_RE.test(name)) continue; // shell-inert display id
541	        if (containers.some((c) => c.name === name)) continue;
542	        const mounts = (seg[3] ?? "")
543	          .split(",")
544	          .map((m) => cleanText(m, 256))
545	          .filter((m) => m.length > 0)
546	          .slice(0, 12);
547	        containers.push({
548	          name,
549	          image: cleanText(seg[1] ?? "", 200),
550	          ports: cleanText(seg[2] ?? "", 200),
551	          mounts,
552	        });
553	      } else if (parts[0] === "PORT") {
554	        if (ports.length >= MAX_PORTS) continue;
555	        const body = parts.slice(1).join("\t").trim();
556	        const toks = body.split(/\s+/);
557	        if (toks.length < 4) continue;
558	        const local = toks[3]; // ss and netstat both put the local addr:port at index 3
559	        const pm = /:(\d{1,5})$/.exec(local);
560	        if (!pm) continue;
561	        const portNum = Number(pm[1]);
562	        if (!Number.isInteger(portNum) || portNum < 1 || portNum > 65535) continue;
563	        // Owning process: ss ⇒ users:(("name",…  ;  netstat ⇒ trailing "pid/name".
564	        let proc = "";
565	        const ssm = /users:\(\("([^"]+)"/.exec(body);
566	        if (ssm) proc = ssm[1];
567	        else {
568	          const nsm = /\s(\d+)\/([^\s]+)\s*$/.exec(body);
569	          if (nsm) proc = nsm[2];
570	        }
571	        proc = cleanText(proc, 64);
572	        const dedup = `${portNum}/${proc}`;
573	        if (seenPort.has(dedup)) continue;
574	        seenPort.add(dedup);
575	        ports.push({ port: portNum, proc, role: mapPortRole(portNum) });
576	      } else if (parts[0] === "SVC" && parts.length >= 2) {
577	        if (services.length >= MAX_SERVICES) continue;
578	        const name = cleanText(parts[1], 128);
579	        if (!SVCNAME_RE.test(name)) continue;
580	        if (services.some((s) => s.name === name)) continue;
581	        services.push({ name });
582	      }
583	    }
584	
585	    // Prune web roots that are ancestors of another detected root (avoid copying
586	    // a parent AND its children — e.g. drop /var/www when /var/www/html exists).
587	    const pruned = webRoots.filter(
588	      (a) => !webRoots.some((b) => b.path !== a.path && b.path.startsWith(a.path + "/"))
589	    );
590	    webRoots.length = 0;
591	    webRoots.push(...pruned.slice(0, MAX_WEB_ROOTS));
592	    homes.splice(MAX_HOMES);
593	
594	    // Merge candidate app dirs into a migratable list, deduped against web roots /
595	    // home dirs (and each other) so a directory is never listed — or copied — twice.
596	    // A path clashes if it equals, contains, or is contained by an already-known path.
597	    const known = [...webRoots.map((w) => w.path), ...homes.map((h) => h.path)];
598	    const appDirs: DetectedAppDir[] = [];
599	    for (const a of rawAppDirs) {
600	      if (appDirs.length >= MAX_APP_DIRS) break;
601	      const clashesKnown = known.some(
602	        (p) => a.path === p || a.path.startsWith(p + "/") || p.startsWith(a.path + "/")
603	      );
604	      if (clashesKnown) continue;
605	      const clashesApp = appDirs.some(
606	        (b) => a.path === b.path || a.path.startsWith(b.path + "/") || b.path.startsWith(a.path + "/")
607	      );
608	      if (clashesApp) continue;
609	      appDirs.push(a);
610	    }
611	    appDirs.sort((x, y) => parseSizeLabel(y.sizeLabel) - parseSizeLabel(x.sizeLabel));
612	    if (appDirs.length > 0) {
613	      notes.push(
614	        `Found ${appDirs.length} app ${appDirs.length === 1 ? "directory" : "directories"} outside the standard web folders (from running processes / app files).`
615	      );
616	    }
617	    if (containers.length > 0) {
618	      notes.push(
619	        `Detected ${containers.length} running Docker ${containers.length === 1 ? "container" : "containers"} — we copy their data/compose files; re-create the containers on the new server.`
620	      );
621	    }
622	
623	    // ---- 2. Databases — only if the customer supplied DB creds ------------
624	    const hasSafePass =
625	      !!input.dbPassword && !input.dbPassword.includes("\n") && !input.dbPassword.includes("\r");
626	    if (input.dbPassword && !hasSafePass) {
627	      notes.push("Database password contains unsupported characters — databases were skipped.");
628	    }
629	
630	    for (const eng of ["mysql", "postgres"] as const) {
631	      const st = engineState[eng];
632	      const rec: DetectedEngine = { engine: eng, present: st.present, listening: st.listening, listed: false };
633	      if (st.present && hasSafePass) {
634	        const effUser = (input.dbUser && input.dbUser.trim()) || (eng === "mysql" ? "root" : "postgres");
635	        if (!DBUSER_RE.test(effUser)) {
636	          notes.push(`Database user "${effUser}" has unsupported characters — ${eng} databases were skipped.`);
637	        } else {
638	          try {
639	            const found =
640	              eng === "mysql"
641	                ? await listMysql(conn, effUser, input.dbPassword!)
642	                : await listPostgres(conn, effUser, input.dbPassword!);
643	            for (const d of found) {
644	              if (databases.length >= MAX_DATABASES) break;
645	              databases.push(d);
646	            }
647	            rec.listed = true;
648	          } catch (e: any) {
649	            notes.push(
650	              `${eng === "mysql" ? "MySQL" : "PostgreSQL"} is installed but we couldn't read its databases with those credentials — you can add databases manually.`
651	            );
652	          }
653	        }
654	      } else if (st.present && !input.dbPassword) {
655	        notes.push(
656	          `${eng === "mysql" ? "MySQL" : "PostgreSQL"} detected — add a database password to include databases in the migration.`
657	        );
658	      }
659	      engines.push(rec);
660	    }
661	
662	    databases.sort((a, b) => parseSizeLabel(b.sizeLabel) - parseSizeLabel(a.sizeLabel));
663	    ports.sort((a, b) => a.port - b.port);
664	
665	    return { ok: true, webRoots, homes, databases, engines, appDirs, containers, ports, services, notes };
666	  } finally {
667	    try {
668	      conn.end();
669	    } catch {
670	      /* best-effort */
671	    }
672	  }
673	}
674	
675	/** Enumerate MySQL/MariaDB schemas + sizes. Creds read from /dev/stdin (never argv). */
676	async function listMysql(conn: Client, user: string, pass: string): Promise<DetectedDatabase[]> {
677	  // `--defaults-extra-file=/dev/stdin` makes mysql read the [client] block from
678	  // the STDIN we stream below — the password never appears on the command line.
679	  const query =
680	    "SELECT table_schema, IFNULL(SUM(data_length+index_length),0) " +
681	    "FROM information_schema.tables GROUP BY table_schema;";
682	  const cnf = `[client]\nuser=${user}\npassword=${pass}\nhost=127.0.0.1\nprotocol=tcp\n`;
683	  const r = await execRemoteInput(
684	    conn,
685	    `mysql --defaults-extra-file=/dev/stdin -N -B -e ${shSingleQuote(query)}`,
686	    cnf,
687	    DB_TIMEOUT_MS
688	  );
689	  if (r.code !== 0) throw new Error(r.stderr.slice(0, 200) || `mysql exit ${r.code}`);
690	  const out: DetectedDatabase[] = [];
691	  for (const line of r.stdout.split("\n")) {
692	    const [name, bytes] = line.replace(/\r$/, "").split("\t");
693	    if (!name || SYSTEM_SCHEMAS.has(name.toLowerCase())) continue;
694	    if (!DBNAME_RE.test(name)) continue;
695	    out.push({ engine: "mysql", name, sizeLabel: humanBytes(Number(bytes) || 0) });
696	  }
697	  return out;
698	}
699	
700	/** Enumerate PostgreSQL databases + sizes. Creds read from /dev/stdin (.pgpass). */
701	async function listPostgres(conn: Client, user: string, pass: string): Promise<DetectedDatabase[]> {
702	  const query =
703	    "SELECT datname, pg_database_size(datname) FROM pg_database WHERE datistemplate = false;";
704	  const pgpass = `127.0.0.1:5432:*:${user}:${pass}\n`;
705	  const r = await execRemoteInput(
706	    conn,
707	    `PGPASSFILE=/dev/stdin psql -h 127.0.0.1 -U ${user} -w -A -t -F '\t' -c ${shSingleQuote(query)}`,
708	    pgpass,
709	    DB_TIMEOUT_MS
710	  );
711	  if (r.code !== 0) throw new Error(r.stderr.slice(0, 200) || `psql exit ${r.code}`);
712	  const out: DetectedDatabase[] = [];
713	  for (const line of r.stdout.split("\n")) {
714	    const [name, bytes] = line.replace(/\r$/, "").split("\t");
715	    if (!name || name === "postgres") continue;
716	    if (!DBNAME_RE.test(name)) continue;
717	    out.push({ engine: "postgres", name, sizeLabel: humanBytes(Number(bytes) || 0) });
718	  }
719	  return out;
720	}
721	
722	/**
723	 * Single-quote a FIXED, code-authored SQL string for the remote shell. The
724	 * inputs here are compile-time constants (never customer data), so this only
725	 * guards the literal `'` inside our own query text.
726	 */
727	function shSingleQuote(s: string): string {
728	  return `'${s.replace(/'/g, `'\\''`)}'`;
729	}
