1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import type { Job } from "@prisma/client";
4	import { runRealMigration, migrationWorkDir } from "./migrate-real";
5	
6	/**
7	 * Real cross-provider transfer is OFF by default. It only runs when the operator
8	 * explicitly sets ENABLE_REAL_MIGRATION=1 (and never in the sandbox). Otherwise
9	 * the safe, progress-reporting SIMULATION below runs. The real engine
10	 * (worker/migrate-real.ts) is hardened against shell injection and never lets a
11	 * secret touch a command string. Enable it only after testing on a throwaway VM.
12	 */
13	const REAL_MIGRATION = process.env.ENABLE_REAL_MIGRATION === "1" && !SANDBOX;
14	
15	/**
16	 * MIGRATE — pull a customer's files + databases from another provider's VPS onto
17	 * their new Nxeon server.
18	 *
19	 * `worker/index.ts` owns the job loop and the `handlers` map; wire this in there:
20	 *   MIGRATE: runMigration,
21	 *
22	 * Ownership + validation happen at enqueue time (lib/actions-migrate.ts), so the
23	 * handler trusts `payload.migrationId`.
24	 *
25	 * SAFETY: real cross-provider transfer (SSH into the source, rsync-pull files,
26	 * mysqldump/pg_dump → import on target) is involved infra that has to be built
27	 * out carefully — see the TODO(real migration) block below. For now this runs a
28	 * SANDBOX-SAFE SIMULATION that walks realistic stages and reports progress, so
29	 * it is harmless to run against real infrastructure. It NEVER opens a real SSH
30	 * connection to the customer's source box.
31	 *
32	 * On completion (DONE or FAILED) every stored source secret is CLEARED:
33	 * `sourcePasswordEnc` and each database's `passEnc`. A finished Migration row
34	 * therefore never retains usable credentials.
35	 */
36	
37	type MigratePayload = { migrationId?: string };
38	type MigrationItems = {
39	  paths?: string[];
40	  databases?: { engine: string; name: string; user: string; passEnc?: string }[];
41	};
42	
43	const MAX_LOG_CHARS = 8000;
44	
45	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
46	
47	/** Append a timestamped line to a log tail, keeping it bounded. */
48	function appendLog(prev: string | null | undefined, line: string): string {
49	  const stamp = new Date().toISOString().slice(11, 19);
50	  const next = `${prev ?? ""}${prev ? "\n" : ""}[${stamp}] ${line}`;
51	  return next.length > MAX_LOG_CHARS ? next.slice(next.length - MAX_LOG_CHARS) : next;
52	}
53	
54	async function loadMigration(job: Job) {
55	  const payload = (job.payload ?? {}) as MigratePayload;
56	  if (!payload.migrationId) throw new Error("migrate job: missing migrationId");
57	  const migration = await db.migration.findUnique({ where: { id: payload.migrationId } });
58	  if (!migration) throw new Error(`Migration ${payload.migrationId} not found`);
59	  // Migration has no Prisma relation to Server (serverId is a plain FK) — resolve
60	  // the target server row separately. `dedicatedIp` is needed by the real engine
61	  // to compute the SSH connection target.
62	  const server = await db.server.findUnique({
63	    where: { id: migration.serverId },
64	    include: { dedicatedIp: true },
65	  });
66	  return { ...migration, server };
67	}
68	
69	/**
70	 * Strip every source secret from a migration row. Called once the job finishes
71	 * (success or failure) so a completed migration never keeps usable credentials.
72	 */
73	async function clearSecrets(migrationId: string, items: MigrationItems) {
74	  const scrubbed: MigrationItems = {
75	    paths: items.paths ?? [],
76	    databases: (items.databases ?? []).map((d) => ({
77	      engine: d.engine,
78	      name: d.name,
79	      user: d.user,
80	      // passEnc dropped entirely
81	    })),
82	  };
83	  await db.migration.update({
84	    where: { id: migrationId },
85	    data: { sourcePasswordEnc: null, items: scrubbed as any },
86	  });
87	}
88	
89	async function report(
90	  migrationId: string,
91	  progress: number,
92	  step: string,
93	  logLine: string,
94	  logTail: string | null
95	): Promise<string> {
96	  const log = appendLog(logTail, logLine);
97	  await db.migration.update({
98	    where: { id: migrationId },
99	    data: { status: "RUNNING", progress, step, log },
100	  });
101	  return log;
102	}
103	
104	async function notify(userId: string, title: string, body?: string, href?: string) {
105	  try {
106	    await db.notification.create({ data: { userId, title, body, href } });
107	  } catch (e) {
108	    console.error("[migrate] notify failed", e);
109	  }
110	}
111	
112	export async function runMigration(job: Job): Promise<void> {
113	  const migration = await loadMigration(job);
114	  const items = (migration.items ?? {}) as MigrationItems;
115	  const paths = items.paths ?? [];
116	  const databases = items.databases ?? [];
117	  const target = migration.server;
118	  const targetName = target ? target.label || target.hostname : "your server";
119	
120	  // Fresh start (also lets a retried job re-enter cleanly).
121	  let log = appendLog(null, `Starting migration from ${migration.sourceUser}@${migration.sourceHost}:${migration.sourcePort} → ${targetName}`);
122	  await db.migration.update({
123	    where: { id: migration.id },
124	    data: { status: "RUNNING", progress: 5, step: "Starting", log, lastError: null, finishedAt: null },
125	  });
126	
127	  // Shared progress reporter: threads the bounded log tail through each update so
128	  // both the real engine and the simulation write to the same Migration row.
129	  const reportStep = async (progress: number, step: string, line: string) => {
130	    log = await report(migration.id, progress, step, line, log);
131	  };
132	
133	  try {
134	    if (REAL_MIGRATION) {
135	      // ---- REAL transfer (hardened; opt-in via ENABLE_REAL_MIGRATION) --------
136	      await runRealMigration({
137	        migration: {
138	          id: migration.id,
139	          sourceHost: migration.sourceHost,
140	          sourcePort: migration.sourcePort,
141	          sourceUser: migration.sourceUser,
142	          sourcePasswordEnc: migration.sourcePasswordEnc,
143	        },
144	        target: target as any,
145	        items,
146	        report: reportStep,
147	      });
148	
149	      await db.migration.update({
150	        where: { id: migration.id },
151	        data: { status: "DONE", progress: 100, step: "Completed", finishedAt: new Date() },
152	      });
153	      await clearSecrets(migration.id, items);
154	
155	      const workDir = migrationWorkDir(migration.id);
156	      await notify(
157	        migration.userId,
158	        `Migration to ${targetName} completed`,
159	        `Copied ${paths.length} path(s) and dumped ${databases.length} database(s) onto ${targetName}. ` +
160	          `Files are staged under ${workDir}/files and database dumps under ${workDir}/dumps — ` +
161	          `move the files into place and import the dumps, then point your DNS at the new server.`,
162	        "/dashboard/migrate"
163	      );
164	      return;
165	    }
166	
167	    // ---- Staged, progress-reporting SIMULATION (default) ----------------------
168	    // Delays are short so the UI polls a live-feeling progression without holding
169	    // the worker loop for long. NEVER opens a real SSH connection to the source.
170	    await reportStep(10, "Connecting to source…", `Connecting to ${migration.sourceHost} over SSH (port ${migration.sourcePort})`);
171	    await sleep(SANDBOX ? 600 : 1200);
172	    await reportStep(18, "Connecting to source…", "Authenticated. Probing disk usage and installed services.");
173	    await sleep(SANDBOX ? 500 : 1000);
174	
175	    // Files stage.
176	    await reportStep(40, "Copying files…", paths.length ? `Copying ${paths.length} path(s): ${paths.join(", ")}` : "No file paths selected — skipping file copy.");
177	    for (const p of paths) {
178	      await sleep(SANDBOX ? 250 : 500);
179	      await reportStep(40, "Copying files…", `  rsync ${p} → ${targetName}:${p}`);
180	    }
181	
182	    // Databases stage.
183	    await reportStep(70, "Dumping databases…", databases.length ? `Dumping ${databases.length} database(s) on the source.` : "No databases selected — skipping database migration.");
184	    for (const d of databases) {
185	      await sleep(SANDBOX ? 250 : 500);
186	      const tool = d.engine === "postgres" ? "pg_dump" : "mysqldump";
187	      await reportStep(70, "Dumping databases…", `  ${tool} ${d.name} (user ${d.user})`);
188	    }
189	
190	    // Import stage.
191	    await reportStep(90, "Importing on target…", `Restoring files and databases onto ${targetName}.`);
192	    await sleep(SANDBOX ? 600 : 1200);
193	    for (const d of databases) {
194	      await sleep(SANDBOX ? 200 : 400);
195	      const tool = d.engine === "postgres" ? "psql" : "mysql";
196	      await reportStep(90, "Importing on target…", `  ${tool} < ${d.name}.sql`);
197	    }
198	
199	    // Finalise.
200	    await reportStep(100, "Finalising…", "Verifying transfer and cleaning up temporary dumps.");
201	    await sleep(SANDBOX ? 400 : 800);
202	
203	    await db.migration.update({
204	      where: { id: migration.id },
205	      data: { status: "DONE", progress: 100, step: "Completed", finishedAt: new Date() },
206	    });
207	    // Security: drop all source credentials now that the job is done.
208	    await clearSecrets(migration.id, items);
209	
210	    await notify(
211	      migration.userId,
212	      `Migration to ${targetName} completed`,
213	      `Moved ${paths.length} path(s) and ${databases.length} database(s). Point your DNS at the new server and restart services when ready.`,
214	      "/dashboard/migrate"
215	    );
216	  } catch (e: any) {
217	    const lastError = `${e?.message ?? e}`.slice(0, 1000);
218	    console.error(`[migrate] migration ${migration.id} failed:`, e);
219	    log = appendLog(log, `ERROR: ${lastError}`);
220	    await db.migration
221	      .update({
222	        where: { id: migration.id },
223	        data: { status: "FAILED", step: "Failed", lastError, log, finishedAt: new Date() },
224	      })
225	      .catch(() => {});
226	    // Security: clear the stored source password/DB secrets even on failure.
227	    await clearSecrets(migration.id, items).catch(() => {});
228	    await notify(
229	      migration.userId,
230	      `Migration to ${targetName} failed`,
231	      lastError,
232	      "/dashboard/migrate"
233	    );
234	    // Swallow — the failure is recorded on the Migration row. Re-throwing would
235	    // make the job loop retry a migration whose secrets we've already cleared.
236	  }
237	}
