276	/**
277	 * READ-ONLY auto-detection of a source box for the beginner wizard. Verifies the
278	 * caller owns the TARGET server (authz + a stricter rate limit than create),
279	 * validates the source connection details, then SSHes into the source and
280	 * inventories web roots / home directories / databases — never writing anything
281	 * on the source and never persisting the supplied credentials.
282	 *
283	 * The plaintext SSH/DB passwords are used in-memory for this one call only and
284	 * are NOT stored anywhere; the client re-supplies them to createMigration once
285	 * the customer confirms what to move. Returns a secret-free ScanResult.
286	 *
287	 * In SANDBOX (staging) this returns realistic SYNTHETIC results and never opens
288	 * a real SSH connection, so staging stays fully self-contained.
289	 */
290	export async function scanSource(input: {
291	  serverId: string;
292	  sourceHost: string;
293	  sourcePort?: number;
294	  sourceUser?: string;
295	  sourcePassword: string;
296	  dbUser?: string;
297	  dbPassword?: string;
298	}): Promise<{ error?: string; scan?: ScanResult }> {
299	  const { user } = await ownedTargetServer(input.serverId);
300	
301	  // Scanning SSHes into an arbitrary customer-named host, so throttle it harder
302	  // than migration creation to stop the wizard being used to probe hosts.
303	  const rl = checkRateLimit(`migrate:scan:${user.id}`, { max: 8, windowMs: 10 * 60 * 1000 });
304	  if (!rl.ok) {
305	    return { error: `Too many scans — please wait ${rl.retryAfterSec}s and try again.` };
306	  }
307	
308	  const host = (input.sourceHost ?? "").trim();
309	  if (!host || host.length > 253 || !HOST_RE.test(host)) {
310	    return { error: "Enter a valid source host — an IP address or domain name." };
311	  }
312	  const port = input.sourcePort ?? 22;
313	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
314	    return { error: "SSH port must be between 1 and 65535." };
315	  }
316	  const sourceUser = (input.sourceUser ?? "root").trim();
317	  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
318	    return { error: "Enter the SSH username on the source server." };
319	  }
320	  if (!input.sourcePassword || input.sourcePassword.length < 1) {
321	    return { error: "Enter the SSH password for the source server." };
322	  }
323	
324	  await db.auditLog.create({
325	    data: { userId: user.id, action: "migration.scan", detail: `${sourceUser}@${host}:${port}` },
326	  }).catch(() => {});
327	
328	  // SANDBOX: never touch the outside world — hand back synthetic detection.
329	  if (SANDBOX) {
330	    return { scan: syntheticScan({ dbPassword: input.dbPassword }) };
331	  }
332	
333	  // Hard overall timeout so a slow/hostile source can't hang the request.
334	  const HARD_TIMEOUT_MS = 90_000;
335	  try {
336	    const scan = await Promise.race<ScanResult>([
337	      detectSource({
338	        host,
339	        port,
340	        user: sourceUser,
341	        password: input.sourcePassword,
342	        dbUser: input.dbUser?.trim() || undefined,
343	        dbPassword: input.dbPassword || undefined,
344	      }),
345	      new Promise<ScanResult>((_, reject) =>
346	        setTimeout(() => reject(new Error("Scan timed out — the source server took too long to respond.")), HARD_TIMEOUT_MS)
347	      ),
348	    ]);
349	    return { scan };
350	  } catch (e: any) {
351	    const msg = `${e?.message ?? e}`;
352	    // Map the common connection failures to friendly, non-leaky copy.
353	    if (/authentication|denied|password/i.test(msg)) {
354	      return { error: "Couldn't sign in to the source server — check the SSH username and password." };
355	    }
356	    if (/ECONNREFUSED|ETIMEDOUT|EHOSTUNREACH|ENOTFOUND|timed out|getaddrinfo/i.test(msg)) {
357	      return { error: "Couldn't reach the source server — check the host and SSH port." };
358	    }
359	    return { error: "We couldn't scan that server. Double-check the details and try again." };
360	  }
361	}
