363	/** The current user's migrations, newest first, WITHOUT any decrypted secrets. */
364	export async function listMigrations(): Promise<MigrationRow[]> {
365	  const user = await requireUser();
366	  const rows = await db.migration.findMany({
367	    where: { userId: user.id },
368	    orderBy: { createdAt: "desc" },
369	  });
370	  const serverIds = [...new Set(rows.map((r) => r.serverId))];
371	  const servers = await db.server.findMany({
372	    where: { id: { in: serverIds } },
373	    select: { id: true, hostname: true, label: true },
374	  });
375	  const byId = new Map(servers.map((s) => [s.id, s]));
376	  return rows.map((m) => toRow(m, byId.get(m.serverId) ?? null));
377	}
