743	function MigrationProgress({ id, onDone }: { id: string; onDone: () => void }) {
744	  const [row, setRow] = useState<MigrationRow | null>(null);
745	  const [error, setError] = useState<string | null>(null);
746	
747	  useEffect(() => {
748	    let cancelled = false;
749	    let timer: ReturnType<typeof setTimeout>;
750	
751	    async function poll() {
752	      try {
753	        const m = await getMigration(id);
754	        if (cancelled) return;
755	        setRow(m);
756	        if (m && (m.status === "DONE" || m.status === "FAILED")) return; // stop polling
757	      } catch {
758	        if (!cancelled) setError("Lost connection while checking progress.");
759	      }
760	      if (!cancelled) timer = setTimeout(poll, 3000);
761	    }
762	    poll();
763	    return () => {
764	      cancelled = true;
765	      clearTimeout(timer);
766	    };
767	  }, [id]);
768	
769	  const progress = row?.progress ?? 0;
770	  const done = row?.status === "DONE";
771	  const failed = row?.status === "FAILED";
772	
773	  return (
774	    <div className="space-y-6">
775	      <div className="card">
776	        <div className="mb-4 flex items-center justify-between">
777	          <h2 className="font-semibold">Migration in progress</h2>
778	          {row && <StatusDot status={row.status} />}
779	        </div>
780	
781	        {error && <div className="mb-4 rounded-xl border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-sm text-amber-300">{error}</div>}
782	
783	        <div className="mb-2 flex items-center justify-between text-sm">
784	          <span className="text-slate-300">{row?.step ?? "Queued…"}</span>
