import { Client, type ClientChannel, type SFTPWrapper } from "ssh2";
import { connectionTarget, serverRootPassword } from "../lib/sftp";
import { decryptSecret } from "../lib/crypto-box";

/**
 * SECURE real cross-provider LIFT-AND-SHIFT migration engine (gated behind
 * ENABLE_REAL_MIGRATION).
 *
 * This automates a whole-server move: it copies the selected apps/web roots/home
 * dirs/Docker data to the SAME absolute paths on the new Nxeon server, dumps and
 * imports the databases WITHOUT ever asking the customer for a DB password (we
 * have root SSH into the source, so we dump via root's LOCAL socket/peer auth),
 * installs the prerequisites the source needs (Docker + compose, DB engines, web
 * servers, runtimes) from a FIXED package allowlist, brings Docker Compose
 * projects up, best-effort enables services + web vhosts, then VERIFIES what is
 * actually running. The final summary honestly separates "migrated & running"
 * (verified) from "copied — needs a manual step".
 *
 * The security bar from the original transfer engine is UNCHANGED and extended:
 *
 *   1. STRICT ALLOWLIST VALIDATION. Every non-secret value that is interpolated
 *      into a command — source host/port/user, file paths, DB engine names,
 *      Docker volume/compose-dir names, systemd service names, listening ports —
 *      must match a shell-inert allowlist regex or it is REJECTED (never
 *      sanitized). The permitted charsets contain no shell metacharacters, so an
 *      interpolated value cannot break out of the command. Anything that came
 *      BACK from the untrusted source scan is re-validated here before use.
 *
 *   2. FIXED PACKAGE ALLOWLIST. Package installs on the target only ever use
 *      compile-time-constant package strings from PKG_* below — never a string
 *      supplied by the source.
 *
 *   3. SECRETS NEVER TOUCH A COMMAND STRING. The source SSH password is written
 *      to a 0600 file over SFTP (bytes, not an argv token) and consumed with
 *      `sshpass -f`. Database dumps use root's LOCAL auth on each side (unix
 *      socket / peer), so NO database password exists to leak. DB contents are
 *      streamed to dump files and never echoed to logs.
 *
 *   4. Everything is confined to a per-migration work dir for transient state
 *      (pass file, known_hosts, DB dumps), bounded by timeouts, and the SSH
 *      password file is scrubbed in a `finally` block regardless of outcome.
 *
 * Best-effort steps (DB dump/import, prerequisite installs, compose up, service
 * enable, vhost copy) LOG their failure reason and continue — a single failed
 * sub-step must not fail the whole migration. Only a fatal setup error throws.
 */

type ReportFn = (progress: number, step: string, line: string) => Promise<void>;

type MigrationRow = {
  id: string;
  sourceHost: string;
  sourcePort: number;
  sourceUser: string;
  sourcePasswordEnc: string | null;
};

type TargetServer = {
  id: string;
  rootPassword: string | null;
  rootPasswordEnc?: string | null;
  sshPort: number | null;
  dedicatedIp?: { address: string } | null;
};

// The secret-free detection snapshot stored under Migration.items.scan. Used here
// only to log standalone containers and derive fallbacks; every field is
// re-validated before it can flow into a command.
type ScanSnapshot = {
  engines?: { engine?: string; present?: boolean }[];
  containers?: { name?: string; image?: string; ports?: string; mounts?: string[] }[];
  ports?: { port?: number; proc?: string; role?: string }[];
  services?: { name?: string }[];
  appDirs?: { path?: string; runtime?: string; signature?: string }[];
};

type Items = {
  paths?: string[];
  // Legacy per-DB list (with encrypted password) — no longer used for dumping;
  // kept optional so old rows still type-check. Passwordless dumping uses dbEngines.
  databases?: { engine: string; name: string; user: string; passEnc?: string }[];
  dbEngines?: string[]; // which engines to dump via source root LOCAL auth
  dockerVolumes?: string[]; // named docker volumes to copy (/var/lib/docker/volumes/<n>/_data)
  composeDirs?: string[]; // compose project dirs → `docker compose up -d`
  verifyPorts?: number[]; // ports that should be listening on the target after bring-up
  hasContainers?: boolean; // Docker containers detected → install Docker Engine + compose
  webServers?: string[]; // "nginx" | "apache" to install + enable vhosts for
  runtimes?: string[]; // "nodejs" | "python3" to install
  scan?: ScanSnapshot;
};

// A single line item in the honest final summary.
export type MigrationStepResult = {
  step: string;
  // running  = verified running on the target
  // copied   = placed on the target but NOT verified running (may need a manual step)
  // failed   = attempted, failed (reason in detail) — did NOT fail the migration
  // skipped  = nothing to do
  status: "running" | "copied" | "failed" | "skipped";
  detail: string;
};

export type RealMigrationSummary = {
  results: MigrationStepResult[];
  verifiedRunning: string[];
  needsAttention: string[];
};

export type RealMigrationInput = {
  migration: MigrationRow;
  target: TargetServer | null;
  items: Items;
  report: ReportFn;
};

// ---- Timeouts -------------------------------------------------------------
const CONNECT_TIMEOUT_MS = 20_000;
const SETUP_TIMEOUT_MS = 60_000; // small writes, checks
const INSTALL_TIMEOUT_MS = 10 * 60_000; // package installs (apt/dnf can be slow)
const TRANSFER_TIMEOUT_MS = Number(process.env.MIGRATE_EXEC_TIMEOUT_MS ?? 45 * 60_000); // rsync/dump/import

// ---- Strict allowlist validators (throw/reject on any violation) ----------
// Charsets below are deliberately shell-inert: no quotes, spaces, metachars or
// newlines. Validated values are therefore safe to interpolate into a command.
const HOSTNAME_RE = /^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$/;
const IPV4_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;
const IPV6_RE = /^[0-9A-Fa-f:]{2,45}$/;
const USER_RE = /^[a-z_][a-z0-9_-]{0,31}$/;
const PATH_RE = /^\/[A-Za-z0-9._/-]{0,255}$/; // absolute path, safe charset
// Docker volume name (docker's own charset) and systemd unit name — shell-inert.
const VOLNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
const SVCNAME_RE = /^[A-Za-z0-9@][A-Za-z0-9@._-]{0,127}$/;

// Top-level system locations we refuse to overwrite on the target even if a
// (validated) path points at one — a lift-and-shift must never clobber the new
// server's own OS. Docker volumes/state are handled by their dedicated steps.
const UNSAFE_PREFIXES = [
  "/bin", "/sbin", "/usr", "/lib", "/lib64", "/etc/systemd", "/proc", "/sys",
  "/dev", "/run", "/boot", "/var/lib/docker",
];
const UNSAFE_EXACT = new Set(["/", "/etc", "/var", "/var/lib", "/usr", "/home", "/root/.ssh"]);

function assert(cond: unknown, msg: string): asserts cond {
  if (!cond) throw new Error(msg);
}

function validHost(h: string): boolean {
  return typeof h === "string" && (HOSTNAME_RE.test(h) || IPV4_RE.test(h) || IPV6_RE.test(h));
}

function validPath(p: string): boolean {
  return typeof p === "string" && PATH_RE.test(p) && !p.includes("..") && !p.includes("//");
}

/** A validated path we are willing to rsync directly onto the target's real fs. */
function safeCopyTarget(p: string): boolean {
  if (!validPath(p)) return false;
  if (UNSAFE_EXACT.has(p)) return false;
  for (const pre of UNSAFE_PREFIXES) if (p === pre || p.startsWith(pre + "/")) return false;
  return true;
}

/** dirname of a validated absolute path (both inputs/outputs are shell-inert). */
function parentDir(p: string): string {
  const i = p.lastIndexOf("/");
  return i <= 0 ? "/" : p.slice(0, i);
}

// ---- SSH plumbing ---------------------------------------------------------
function execRemote(
  conn: Client,
  cmd: string,
  timeoutMs: number
): Promise<{ code: number; stdout: string; stderr: string }> {
  return new Promise((resolve, reject) => {
    conn.exec(cmd, (err, stream: ClientChannel) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      const timer = setTimeout(() => {
        try {
          stream.close();
        } catch {
          /* ignore */
        }
        reject(new Error("remote command timed out"));
      }, timeoutMs);
      stream
        .on("close", (code: number) => {
          clearTimeout(timer);
          resolve({ code: code ?? 0, stdout, stderr });
        })
        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
    });
  });
}

/** Write bytes to a remote file over SFTP with a fixed 0600 mode (no shell). */
function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const ws = sftp.createWriteStream(path, { mode: 0o600 });
    ws.on("close", () => resolve());
    ws.on("error", (e: Error) => reject(e));
    ws.end(Buffer.from(content, "utf8"));
  });
}

function connectTarget(server: TargetServer): Promise<{ conn: Client; sftp: SFTPWrapper }> {
  return new Promise((resolve, reject) => {
    const target = connectionTarget(server as any);
    if (!target) return reject(new Error("target server is not reachable yet — connection details are pending"));
    const password = serverRootPassword(server);
    if (!password) return reject(new Error("target server has no root password on record"));
    const conn = new Client();
    conn.on("ready", () => {
      conn.sftp((err, sftp) => {
        if (err) return reject(err);
        resolve({ conn, sftp });
      });
    });
    conn.on("error", (e) => reject(e instanceof Error ? e : new Error(String(e))));
    conn.connect({
      host: target.host,
      port: target.port,
      username: "root",
      password,
      readyTimeout: CONNECT_TIMEOUT_MS,
    });
  });
}

// ---- Prerequisite install (FIXED allowlist — never source-supplied) -------
type PkgKey = "docker" | "mysql" | "postgresql" | "nginx" | "apache" | "nodejs" | "python3";

// Command that succeeds iff the package's main binary is already present.
const PKG_CHECK: Record<PkgKey, string> = {
  docker: "command -v docker >/dev/null 2>&1",
  mysql: "command -v mysql >/dev/null 2>&1 || command -v mariadb >/dev/null 2>&1",
  postgresql: "command -v psql >/dev/null 2>&1",
  nginx: "command -v nginx >/dev/null 2>&1",
  apache: "command -v apache2 >/dev/null 2>&1 || command -v httpd >/dev/null 2>&1",
  nodejs: "command -v node >/dev/null 2>&1",
  python3: "command -v python3 >/dev/null 2>&1",
};
// Debian/Ubuntu (apt) package strings — the primary target for Nxeon servers.
const PKG_APT: Record<PkgKey, string> = {
  docker: "docker.io docker-compose-plugin",
  mysql: "mariadb-server mariadb-client",
  postgresql: "postgresql",
  nginx: "nginx",
  apache: "apache2",
  nodejs: "nodejs npm",
  python3: "python3 python3-pip",
};
// RHEL/Fedora (dnf/yum) fallback package strings.
const PKG_DNF: Record<PkgKey, string> = {
  docker: "docker docker-compose-plugin",
  mysql: "mariadb-server mariadb",
  postgresql: "postgresql-server postgresql",
  nginx: "nginx",
  apache: "httpd",
  nodejs: "nodejs npm",
  python3: "python3 python3-pip",
};
// A friendly label for the log/summary.
const PKG_LABEL: Record<PkgKey, string> = {
  docker: "Docker Engine + compose",
  mysql: "MySQL/MariaDB server",
  postgresql: "PostgreSQL server",
  nginx: "nginx",
  apache: "Apache",
  nodejs: "Node.js",
  python3: "Python 3 + pip",
};

/**
 * Idempotently ensure each allowlisted package is present on the target. Runs
 * `apt-get update` once, then for each key: skip if the check passes, else try
 * apt → dnf → yum with the FIXED package string. Returns which were newly
 * installed / already present / failed. Never throws (best-effort per package).
 */
async function ensurePackages(
  conn: Client,
  keys: PkgKey[]
): Promise<{ key: PkgKey; ok: boolean; already: boolean; err?: string }[]> {
  const out: { key: PkgKey; ok: boolean; already: boolean; err?: string }[] = [];
  if (keys.length === 0) return out;
  // Refresh apt metadata once (best-effort; ignored on non-apt systems).
  await execRemote(conn, `apt-get update -y >/dev/null 2>&1 || true`, INSTALL_TIMEOUT_MS).catch(() => {});
  for (const key of keys) {
    const already = await execRemote(conn, PKG_CHECK[key], SETUP_TIMEOUT_MS).then((r) => r.code === 0).catch(() => false);
    if (already) {
      out.push({ key, ok: true, already: true });
      continue;
    }
    // All three package strings are compile-time constants from the allowlist.
    const install =
      `DEBIAN_FRONTEND=noninteractive apt-get install -y ${PKG_APT[key]} ` +
      `|| dnf install -y ${PKG_DNF[key]} ` +
      `|| yum install -y ${PKG_DNF[key]}`;
    const r = await execRemote(conn, install, INSTALL_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
    const nowPresent = await execRemote(conn, PKG_CHECK[key], SETUP_TIMEOUT_MS).then((x) => x.code === 0).catch(() => false);
    if (nowPresent) {
      out.push({ key, ok: true, already: false });
    } else {
      const tail = (r.stderr || r.stdout || "").split("\n").filter(Boolean).slice(-2).join(" ").slice(0, 200);
      out.push({ key, ok: false, already: false, err: tail || `install exit ${r.code}` });
    }
  }
  return out;
}

// ---- Plan derivation (prefer explicit items, re-validate everything) ------
function derivePlan(items: Items) {
  const scan = items.scan ?? {};

  // Engines to dump: explicit dbEngines, else engines the scan marked present.
  const engineSet = new Set<string>();
  for (const e of items.dbEngines ?? []) engineSet.add(e);
  if (engineSet.size === 0) for (const e of scan.engines ?? []) if (e?.present && e.engine) engineSet.add(e.engine);
  const dbEngines = [...engineSet].filter((e): e is "mysql" | "postgres" => e === "mysql" || e === "postgres");

  const dockerVolumes = [...new Set(items.dockerVolumes ?? [])].filter((v) => VOLNAME_RE.test(v)).slice(0, 60);
  const composeDirs = [...new Set(items.composeDirs ?? [])].filter((p) => validPath(p)).slice(0, 40);
  const verifyPorts = [...new Set((items.verifyPorts ?? []).filter((p) => Number.isInteger(p) && p >= 1 && p <= 65535 && p !== 22))].slice(0, 60);
  const hasContainers = !!items.hasContainers || (scan.containers?.length ?? 0) > 0 || composeDirs.length > 0 || dockerVolumes.length > 0;
  const webServers = [...new Set(items.webServers ?? [])].filter((w): w is "nginx" | "apache" => w === "nginx" || w === "apache");
  const runtimes = [...new Set(items.runtimes ?? [])].filter((r): r is "nodejs" | "python3" => r === "nodejs" || r === "python3");
  const services = [...new Set((scan.services ?? []).map((s) => s?.name ?? "").filter((n) => SVCNAME_RE.test(n)))].slice(0, 30);
  const containers = (scan.containers ?? [])
    .map((c) => ({
      name: String(c?.name ?? ""),
      image: String(c?.image ?? ""),
      ports: String(c?.ports ?? ""),
      mounts: Array.isArray(c?.mounts) ? c!.mounts!.map((m) => String(m)) : [],
    }))
    .slice(0, 30);

  const prereqs: PkgKey[] = [];
  if (dbEngines.includes("mysql")) prereqs.push("mysql");
  if (dbEngines.includes("postgres")) prereqs.push("postgresql");
  if (hasContainers) prereqs.push("docker");
  for (const w of webServers) prereqs.push(w === "nginx" ? "nginx" : "apache");
  for (const rt of runtimes) prereqs.push(rt);

  return { dbEngines, dockerVolumes, composeDirs, verifyPorts, hasContainers, webServers, runtimes, services, containers, prereqs };
}

// ---------------------------------------------------------------------------

/**
 * Perform a real lift-and-shift migration. Throws only on a FATAL setup error
 * (validation / target connect); every migration sub-step is best-effort and
 * records its outcome in the returned summary instead of aborting the run.
 */
export async function runRealMigration(input: RealMigrationInput): Promise<RealMigrationSummary> {
  const { migration, target, items, report } = input;
  assert(target, "target server row not found");

  // ---- 1. Validate EVERY non-secret input up front (fail closed) ----------
  const host = migration.sourceHost;
  const port = migration.sourcePort;
  const user = migration.sourceUser;
  assert(validHost(host), "source host is not a valid hostname or IP address");
  assert(Number.isInteger(port) && port >= 1 && port <= 65535, "source SSH port is out of range");
  assert(USER_RE.test(user), "source username contains unsupported characters");

  const rawPaths = (items.paths ?? []).map((p) => p.trim()).filter(Boolean);
  for (const p of rawPaths) assert(validPath(p), `unsupported file path: ${p}`);
  // Direct-to-real-path copy: refuse to overwrite the target's own OS locations.
  const paths = rawPaths.filter(safeCopyTarget);

  const plan = derivePlan(items);
  for (const p of plan.composeDirs) assert(safeCopyTarget(p), `unsupported compose dir: ${p}`);

  assert(paths.length || plan.dbEngines.length || plan.composeDirs.length || plan.dockerVolumes.length, "nothing selected to migrate");

  // Root-vs-sudo prefix for privileged commands ON THE SOURCE (constant strings).
  const priv = user === "root" ? "" : "sudo -n ";

  // ---- 2. Decrypt the ONE secret we still need (source SSH password) ------
  const sshPass = decryptSecret(migration.sourcePasswordEnc);
  assert(sshPass, "source SSH password is missing or could not be decrypted");

  // ---- 3. Connect to the TARGET (our own server) --------------------------
  await report(6, "Connecting…", "Connecting to your Nxeon server to prepare the lift-and-shift.");
  const { conn, sftp } = await connectTarget(target!);

  const work = `/root/nxeon-migrations/${migration.id}`;
  const passFile = `${work}/ssh.pass`;
  const knownHosts = `${work}/known_hosts`;
  const sshOpts =
    `-p ${port} -o StrictHostKeyChecking=accept-new -o UserKnownHostsFile=${knownHosts} ` +
    `-o ConnectTimeout=25 -o PreferredAuthentications=password -o PubkeyAuthentication=no`;
  const srcSpec = `${user}@${host}`;
  // rsync pull from the source over the sshpass-driven ssh (used everywhere below).
  const rsyncPull = (remotePath: string, localParent: string) =>
    `sshpass -f ${passFile} rsync -az --numeric-ids --timeout=1200 -e 'ssh ${sshOpts}' ${srcSpec}:${remotePath} ${localParent}/`;
  // Run a fixed command ON THE SOURCE and capture its output on the target.
  const onSource = (cmd: string) => `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} '${cmd}'`;

  const results: MigrationStepResult[] = [];
  const verifiedRunning: string[] = [];
  const needsAttention: string[] = [];
  const push = (r: MigrationStepResult) => {
    results.push(r);
    if (r.status === "running") verifiedRunning.push(r.step);
    else if (r.status === "copied" || r.status === "failed") needsAttention.push(`${r.step} — ${r.detail}`);
  };

  try {
    // ---- 4. Prepare the target: transfer tools + work dir + secret file ----
    await report(10, "Preparing…", "Ensuring transfer tools (rsync, sshpass) are present on the target.");
    await execRemote(
      conn,
      `command -v rsync >/dev/null 2>&1 && command -v sshpass >/dev/null 2>&1 || ` +
        `{ (apt-get update -y && apt-get install -y rsync sshpass) || (dnf install -y rsync sshpass) || (yum install -y rsync sshpass); }`,
      INSTALL_TIMEOUT_MS
    );
    const tools = await execRemote(conn, `command -v rsync && command -v sshpass`, SETUP_TIMEOUT_MS);
    assert(tools.code === 0, "could not install rsync/sshpass on the target server");

    await execRemote(
      conn,
      `mkdir -p ${work}/dumps && chmod 700 ${work} && touch ${knownHosts} && chmod 600 ${knownHosts}`,
      SETUP_TIMEOUT_MS
    );
    // Write the source SSH password to a 0600 file over SFTP (never a shell arg).
    await sftpWrite(sftp, passFile, sshPass);

    // ---- 5. Install prerequisites on the target (fixed allowlist) ---------
    if (plan.prereqs.length) {
      await report(16, "Installing prerequisites…", `Preparing the target: ${plan.prereqs.map((k) => PKG_LABEL[k]).join(", ")}.`);
      const installed = await ensurePackages(conn, plan.prereqs);
      for (const r of installed) {
        if (r.ok) {
          push({ step: `Install ${PKG_LABEL[r.key]}`, status: "running", detail: r.already ? "already present" : "installed" });
          await report(18, "Installing prerequisites…", `  ${PKG_LABEL[r.key]}: ${r.already ? "already present" : "installed"}.`);
        } else {
          push({ step: `Install ${PKG_LABEL[r.key]}`, status: "failed", detail: r.err ?? "install failed" });
          await report(18, "Installing prerequisites…", `  ${PKG_LABEL[r.key]}: could not install — ${r.err ?? "unknown error"}.`);
        }
      }
      // Make sure DB engines + docker daemon are actually up before we use them.
      if (plan.dbEngines.includes("mysql"))
        await execRemote(conn, `systemctl enable --now mariadb 2>/dev/null || systemctl enable --now mysql 2>/dev/null || service mysql start 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
      if (plan.dbEngines.includes("postgres"))
        await execRemote(conn, `systemctl enable --now postgresql 2>/dev/null || service postgresql start 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
      if (plan.hasContainers)
        await execRemote(conn, `systemctl enable --now docker 2>/dev/null || service docker start 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
    }

    // ---- 6. Files: rsync each selected path to the SAME path on target ----
    if (paths.length) {
      await report(28, "Copying files…", `Copying ${paths.length} path(s) from ${srcSpec} to the same locations on the new server.`);
      let idx = 0;
      let copied = 0;
      for (const p of paths) {
        idx++;
        const destParent = parentDir(p);
        await execRemote(conn, `mkdir -p ${destParent}`, SETUP_TIMEOUT_MS);
        const pct = 28 + Math.round((idx / paths.length) * 22); // 28 → 50
        await report(pct, "Copying files…", `  rsync ${p} → ${p}`);
        const r = await execRemote(conn, rsyncPull(p, destParent), TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
        if (r.code === 0) {
          copied++;
        } else {
          const tail = (r.stderr || r.stdout || "").split("\n").filter(Boolean).slice(-2).join(" ").slice(0, 200);
          push({ step: `Copy ${p}`, status: "failed", detail: tail || `rsync exit ${r.code}` });
          await report(pct, "Copying files…", `  copy failed for ${p}: ${tail || `rsync exit ${r.code}`}`);
        }
      }
      if (copied) push({ step: `Copy ${copied} folder(s) to their original paths`, status: "copied", detail: "files placed at the same paths on the new server" });
    }

    // ---- 7. Named Docker volume data --------------------------------------
    if (plan.dockerVolumes.length) {
      await report(52, "Copying container data…", `Copying ${plan.dockerVolumes.length} named Docker volume(s).`);
      let ok = 0;
      for (const v of plan.dockerVolumes) {
        // Create the volume (idempotent), then rsync its _data into place.
        await execRemote(conn, `docker volume create ${v} >/dev/null 2>&1 || true`, SETUP_TIMEOUT_MS).catch(() => {});
        const dataDir = `/var/lib/docker/volumes/${v}/_data`;
        await execRemote(conn, `mkdir -p ${dataDir}`, SETUP_TIMEOUT_MS).catch(() => {});
        const r = await execRemote(conn, rsyncPull(`${dataDir}`, `/var/lib/docker/volumes/${v}`), TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
        if (r.code === 0) ok++;
        else {
          const tail = (r.stderr || "").split("\n").filter(Boolean).slice(-2).join(" ").slice(0, 200);
          push({ step: `Copy volume ${v}`, status: "failed", detail: tail || `rsync exit ${r.code}` });
        }
      }
      if (ok) push({ step: `Copy ${ok} Docker volume(s)`, status: "copied", detail: "volume data restored under /var/lib/docker/volumes" });
    }

    // ---- 8. Databases: dump via source root LOCAL auth, import on target ---
    for (const engine of plan.dbEngines) {
      await report(60, "Migrating databases…", `Dumping ${engine === "postgres" ? "PostgreSQL" : "MySQL/MariaDB"} from the source (root, no password).`);
      if (engine === "mysql") {
        const dump = `${work}/dumps/mysql-all.sql`;
        // mysqldump over root's LOCAL socket auth (Debian/Ubuntu root = auth_socket).
        const dumpCmd = `${priv}mysqldump --single-transaction --routines --triggers --events --all-databases`;
        const r = await execRemote(conn, `${onSource(dumpCmd)} > ${dump} 2>${work}/dumps/mysql.err`, TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
        const nonEmpty = await execRemote(conn, `test -s ${dump}`, SETUP_TIMEOUT_MS).then((x) => x.code === 0).catch(() => false);
        if (r.code !== 0 || !nonEmpty) {
          const err = await execRemote(conn, `tail -c 200 ${work}/dumps/mysql.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
          push({ step: "Migrate MySQL/MariaDB", status: "failed", detail: `root could not dump via local socket${err ? `: ${err}` : ""} — import skipped` });
          await report(62, "Migrating databases…", `  MySQL dump via root failed — skipping (databases left for manual export).`);
        } else {
          // Import on the target as its own root (socket auth — no password).
          const imp = await execRemote(conn, `mysql < ${dump} 2>${work}/dumps/mysql-import.err`, TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
          if (imp.code === 0) {
            push({ step: "Migrate MySQL/MariaDB databases", status: "copied", detail: "dumped via source root socket and imported on the target" });
            await report(64, "Migrating databases…", `  MySQL databases dumped and imported.`);
          } else {
            const err = await execRemote(conn, `tail -c 200 ${work}/dumps/mysql-import.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
            push({ step: "Import MySQL/MariaDB", status: "failed", detail: `dump succeeded but import failed${err ? `: ${err}` : ""} — dump kept at ${dump}` });
          }
        }
      } else {
        const dump = `${work}/dumps/postgres-all.sql`;
        // pg_dumpall over peer auth as the postgres superuser.
        const dumpCmd = user === "root" ? "sudo -u postgres pg_dumpall" : "sudo -n -u postgres pg_dumpall";
        const r = await execRemote(conn, `${onSource(dumpCmd)} > ${dump} 2>${work}/dumps/pg.err`, TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
        const nonEmpty = await execRemote(conn, `test -s ${dump}`, SETUP_TIMEOUT_MS).then((x) => x.code === 0).catch(() => false);
        if (r.code !== 0 || !nonEmpty) {
          const err = await execRemote(conn, `tail -c 200 ${work}/dumps/pg.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
          push({ step: "Migrate PostgreSQL", status: "failed", detail: `postgres peer dump failed${err ? `: ${err}` : ""} — import skipped` });
          await report(62, "Migrating databases…", `  PostgreSQL dump via peer auth failed — skipping.`);
        } else {
          const imp = await execRemote(conn, `sudo -u postgres psql -f ${dump} >/dev/null 2>${work}/dumps/pg-import.err`, TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
          // pg_dumpall + psql exits 0 even with benign "role already exists" notices.
          if (imp.code === 0) {
            push({ step: "Migrate PostgreSQL databases", status: "copied", detail: "dumped via source postgres peer auth and imported on the target" });
            await report(64, "Migrating databases…", `  PostgreSQL databases dumped and imported.`);
          } else {
            const err = await execRemote(conn, `tail -c 200 ${work}/dumps/pg-import.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
            push({ step: "Import PostgreSQL", status: "failed", detail: `dump succeeded but import reported errors${err ? `: ${err}` : ""} — dump kept at ${dump}` });
          }
        }
      }
    }

    // ---- 9. Docker Compose bring-up ---------------------------------------
    if (plan.composeDirs.length) {
      await report(74, "Starting containers…", `Bringing up ${plan.composeDirs.length} Docker Compose project(s).`);
      for (const dir of plan.composeDirs) {
        // dir has already been copied to the same path in step 6 (or is being copied).
        const r = await execRemote(
          conn,
          `sh -c 'cd ${dir} && { docker compose up -d || docker-compose up -d; }' >/dev/null 2>${work}/dumps/compose.err`,
          TRANSFER_TIMEOUT_MS
        ).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
        if (r.code === 0) {
          push({ step: `Compose up ${dir}`, status: "running", detail: "docker compose up -d succeeded" });
          await report(78, "Starting containers…", `  compose up in ${dir}: started.`);
        } else {
          const err = await execRemote(conn, `tail -c 200 ${work}/dumps/compose.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
          push({ step: `Compose up ${dir}`, status: "failed", detail: `could not start${err ? `: ${err}` : ""} — run 'docker compose up -d' in ${dir}` });
          await report(78, "Starting containers…", `  compose up in ${dir} failed — left for manual start.`);
        }
      }
    }
    // Standalone (non-compose) containers: log a run-equivalent, never auto-run
    // an arbitrary source-supplied image. Honest — these are left for the user.
    for (const c of plan.containers) {
      if (!c.name || !c.image) continue;
      const portsHint = c.ports ? ` ports[${c.ports}]` : "";
      const mountsHint = c.mounts.length ? ` mounts[${c.mounts.join(",")}]` : "";
      push({
        step: `Container ${c.name}`,
        status: "copied",
        detail: `recreate on the new server: image ${c.image}${portsHint}${mountsHint}`,
      });
    }

    // ---- 10. Web-server vhosts (best-effort copy + reload) ----------------
    for (const w of plan.webServers) {
      if (w === "nginx") {
        await execRemote(conn, `mkdir -p /etc/nginx`, SETUP_TIMEOUT_MS).catch(() => {});
        const r = await execRemote(conn, rsyncPull("/etc/nginx/", "/etc/nginx"), TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
        if (r.code === 0) {
          const up = await execRemote(conn, `nginx -t 2>/dev/null && (systemctl reload nginx 2>/dev/null || systemctl restart nginx 2>/dev/null)`, SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
          if (up.code === 0) push({ step: "nginx vhosts", status: "running", detail: "config copied, nginx -t passed, reloaded" });
          else push({ step: "nginx vhosts", status: "copied", detail: "config copied but nginx did not reload cleanly — check `nginx -t`" });
        } else {
          push({ step: "nginx vhosts", status: "failed", detail: "could not copy /etc/nginx from the source" });
        }
      } else {
        await execRemote(conn, `mkdir -p /etc/apache2`, SETUP_TIMEOUT_MS).catch(() => {});
        const r = await execRemote(conn, rsyncPull("/etc/apache2/", "/etc/apache2"), TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
        if (r.code === 0) {
          const up = await execRemote(conn, `apachectl configtest 2>/dev/null && (systemctl reload apache2 2>/dev/null || systemctl restart apache2 2>/dev/null)`, SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
          if (up.code === 0) push({ step: "Apache vhosts", status: "running", detail: "config copied, configtest passed, reloaded" });
          else push({ step: "Apache vhosts", status: "copied", detail: "config copied but Apache did not reload cleanly — check `apachectl configtest`" });
        } else {
          push({ step: "Apache vhosts", status: "failed", detail: "could not copy /etc/apache2 from the source" });
        }
      }
    }

    // ---- 11. systemd services (best-effort copy of the unit + enable) -----
    if (plan.services.length) {
      await report(84, "Re-enabling services…", `Re-enabling up to ${plan.services.length} service(s) that ran on the source.`);
      for (const svc of plan.services) {
        const unit = `/etc/systemd/system/${svc}.service`;
        // Copy the unit file only if it exists on the source (best-effort).
        const r = await execRemote(conn, rsyncPull(unit, "/etc/systemd/system"), SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
        if (r.code !== 0) {
          push({ step: `Service ${svc}`, status: "copied", detail: "unit not a simple /etc/systemd/system file — re-enable manually" });
          continue;
        }
        await execRemote(conn, `systemctl daemon-reload 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
        const en = await execRemote(conn, `systemctl enable --now ${svc} 2>/dev/null`, SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
        const active = await execRemote(conn, `systemctl is-active ${svc} 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim() === "active").catch(() => false);
        if (en.code === 0 && active) push({ step: `Service ${svc}`, status: "running", detail: "unit copied, enabled and active" });
        else push({ step: `Service ${svc}`, status: "copied", detail: "unit copied but not confirmed active — check `systemctl status`" });
      }
    }

    // ---- 12. Verification: DB engines, containers, listening ports --------
    await report(92, "Verifying…", "Checking that databases, containers and services are up on the new server.");
    if (plan.dbEngines.includes("mysql")) {
      const up = await execRemote(conn, `systemctl is-active mariadb 2>/dev/null || systemctl is-active mysql 2>/dev/null || pgrep -x mysqld >/dev/null 2>&1 && echo active`, SETUP_TIMEOUT_MS).then((x) => /active/.test(x.stdout)).catch(() => false);
      push({ step: "MySQL/MariaDB engine", status: up ? "running" : "copied", detail: up ? "engine is active on the target" : "engine not confirmed active — start it manually" });
    }
    if (plan.dbEngines.includes("postgres")) {
      const up = await execRemote(conn, `systemctl is-active postgresql 2>/dev/null || (pgrep -x postgres >/dev/null 2>&1 && echo active)`, SETUP_TIMEOUT_MS).then((x) => /active/.test(x.stdout)).catch(() => false);
      push({ step: "PostgreSQL engine", status: up ? "running" : "copied", detail: up ? "engine is active on the target" : "engine not confirmed active — start it manually" });
    }
    if (plan.hasContainers) {
      const n = await execRemote(conn, `docker ps -q 2>/dev/null | wc -l`, SETUP_TIMEOUT_MS).then((x) => parseInt(x.stdout.trim(), 10) || 0).catch(() => 0);
      push({ step: "Docker containers", status: n > 0 ? "running" : "copied", detail: n > 0 ? `${n} container(s) running on the target` : "no containers running yet — start your compose project(s)" });
      await report(94, "Verifying…", `  docker ps shows ${n} running container(s).`);
    }
    if (plan.verifyPorts.length) {
      const list = plan.verifyPorts.join(" ");
      const out = await execRemote(
        conn,
        `for p in ${list}; do (ss -lnt 2>/dev/null || netstat -lnt 2>/dev/null) | grep -q ":$p " && echo "$p up" || echo "$p down"; done`,
        SETUP_TIMEOUT_MS
      ).then((x) => x.stdout).catch(() => "");
      const upPorts = (out.match(/(\d+) up/g) ?? []).map((s) => s.replace(" up", ""));
      const downPorts = (out.match(/(\d+) down/g) ?? []).map((s) => s.replace(" down", ""));
      if (upPorts.length) push({ step: "Listening ports", status: "running", detail: `now listening on the target: ${upPorts.join(", ")}` });
      if (downPorts.length) push({ step: "Ports not yet listening", status: "copied", detail: `not up on the target yet: ${downPorts.join(", ")} — start the owning app/service` });
      await report(95, "Verifying…", `  ports up: ${upPorts.join(", ") || "none"}; not up: ${downPorts.join(", ") || "none"}.`);
    }

    // ---- 13. Final honest summary ----------------------------------------
    await report(
      97,
      "Finalising…",
      `Migrated & running (verified): ${verifiedRunning.length}. Copied — may need a manual step: ${needsAttention.length}.`
    );
    if (needsAttention.length) {
      await report(98, "Finalising…", `Needs a manual step: ${needsAttention.slice(0, 8).join(" | ")}${needsAttention.length > 8 ? " …" : ""}`);
    }

    return { results, verifiedRunning, needsAttention };
  } finally {
    // Scrub the SSH password file from the target, always. DB dumps under
    // ${work}/dumps are intentionally kept so a failed import can be retried by hand.
    await execRemote(conn, `shred -u ${passFile} 2>/dev/null || rm -f ${passFile}`, SETUP_TIMEOUT_MS).catch(() => {});
    try {
      conn.end();
    } catch {
      /* best-effort */
    }
  }
}

/** Where transient migration state (dumps) lands on the target, for the notice. */
export function migrationWorkDir(migrationId: string): string {
  return `/root/nxeon-migrations/${migration_id_safe(migrationId)}`;
}

function migration_id_safe(id: string): string {
  return /^[A-Za-z0-9_-]{1,64}$/.test(id) ? id : "invalid";
}

