type MigratePayload = { migrationId?: string };
type MigrationItems = {
  paths?: string[];
  // Legacy per-DB list (with encrypted password) — kept optional for old rows.
  databases?: { engine: string; name: string; user: string; passEnc?: string }[];
  // Passwordless lift-and-shift plan (extended TS shape carried through the
  // existing Migration.items Json column — no schema change).
