input.new_string:
async function clearSecrets(
  migrationId: string,
  items: MigrationItems,
  results?: MigrationStepResult[]
) {
  // Preserve every NON-secret field (so the wizard/summary keep working) while
  // stripping the only secret carried in items — each legacy DB's passEnc. The
  // source SSH password (sourcePasswordEnc column) is nulled separately.
  const scrubbed: MigrationItems = {
    ...items,
    databases: (items.databases ?? []).map((d) => ({
      engine: d.engine,
      name: d.name,
      user: d.user,
      // passEnc dropped entirely
    })),
    ...(results ? { results } : {}),
  };
  await db.migration.update({
    where: { id: migrationId },
    data: { sourcePasswordEnc: null, items: scrubbed as any },
  });
}

