if (REAL_MIGRATION) {
  // ---- REAL lift-and-shift (hardened; opt-in via ENABLE_REAL_MIGRATION) --
  const summary = await runRealMigration({
    migration: {
      id: migration.id,
      sourceHost: migration.sourceHost,
      sourcePort: migration.sourcePort,
      sourceUser: migration.sourceUser,
      sourcePasswordEnc: migration.sourcePasswordEnc,
    },
    target: target as any,
    items,
    report: reportStep,
  });

  await db.migration.update({
    where: { id: migration.id },
    data: { status: "DONE", progress: 100, step: "Completed", finishedAt: new Date() },
  });
  // Persist the honest step-by-step summary (secret-free) into items.results.
  await clearSecrets(migration.id, items, summary.results);

  const workDir = migrationWorkDir(migration.id);
  const running = summary.verifiedRunning.length;
  const manual = summary.needsAttention.length;
  const body =
    `Lift-and-shift onto ${targetName} finished. ${running} item(s) migrated & verified running; ` +
    `${manual} copied that may need a manual step. ` +
    (manual ? `To finish: ${summary.needsAttention.slice(0, 5).join(" | ")}${manual > 5 ? " …" : ""}. ` : "") +
    `Any DB dumps that couldn't import were kept under ${workDir}/dumps. Point your DNS at the new server when ready.`;
  await notify(migration.userId, `Migration to ${targetName} completed`, body, "/dashboard/migrate");
  return;
}

