// ---- Staged, progress-reporting SIMULATION (default) ----------------------
// Delays are short so the UI polls a live-feeling progression without holding
// the worker loop for long. NEVER opens a real SSH connection to the source.
await reportStep(10, "Connecting to source…", `Connecting to ${migration.sourceHost} over SSH (port ${migration.sourcePort})`);
await sleep(SANDBOX ? 600 : 1200);
await reportStep(18, "Connecting to source…", "Authenticated. Probing disk usage and installed services.");
await sleep(SANDBOX ? 500 : 1000);

// Files stage.
await reportStep(40, "Copying files…", paths.length ? `Copying ${paths.length} path(s): ${paths.join(", ")}` : "No file paths selected — skipping file copy.");
for (const p of paths) {
  await sleep(SANDBOX ? 250 : 500);
  await reportStep(40, "Copying files…", `  rsync ${p} → ${targetName}:${p}`);
}

// Databases stage.
await reportStep(70, "Dumping databases…", databases.length ? `Dumping ${databases.length} database(s) on the source.` : "No databases selected — skipping database migration.");
for (const d of databases) {
