export type CreateMigrationInput = {
  serverId: string; // target Nxeon server (must be owned by the caller)
  sourceHost: string; // FQDN or IP of the source VPS
  sourcePort?: number; // SSH port, default 22
  sourceUser?: string; // SSH user, default "root" (we use root's LOCAL auth to dump DBs)
  sourcePassword: string; // SSH password for the source box
  paths?: string[]; // file paths to copy from the source (to the same paths on the target)
  /**
   * Read-only auto-detection snapshot (from scanSource). Carries NO secrets. We
   * derive the whole lift-and-shift plan (which DB engines to dump passwordlessly,
   * Docker volumes/compose dirs, prerequisites to install, ports to verify) from
   * it, and store both the plan and the snapshot under Migration.items — reusing
   * the existing Json column rather than adding a schema field (another agent
   * owns the schema this wave).
   */
  scan?: ScanResult;
};

// The passwordless lift-and-shift plan, derived from the scan + selected paths and
// carried through Migration.items (secret-free). The worker re-validates every
// value against strict shell-inert allowlists before it is used in a command.
type MigrationPlan = {
  dbEngines: ("mysql" | "postgres")[];
  dockerVolumes: string[];
  composeDirs: string[];
  verifyPorts: number[];
  hasContainers: boolean;
  webServers: ("nginx" | "apache")[];
  runtimes: ("nodejs" | "python3")[];
};

// Docker volume names are shell-inert (docker's own charset) — the worker
// re-validates, but we only ever store well-formed names.
const VOLNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
function isCopyableAbsPath(p: string): boolean {
  return typeof p === "string" && p.startsWith("/") && !p.includes("..") && p.length > 1;
}

/**
 * Derive the passwordless lift-and-shift plan from the read-only scan and the set
 * of paths the customer chose to copy. Databases are auto-included whenever an
 * engine was detected (no password needed — the worker dumps via root's local
 * socket/peer auth); Docker/web/runtime prerequisites are inferred so the worker
 * can install them on the target. Everything here is secret-free.
 */
function derivePlan(scan: ScanResult | undefined, selectedPaths: string[]): MigrationPlan {
  const empty: MigrationPlan = {
    dbEngines: [],
    dockerVolumes: [],
    composeDirs: [],
    verifyPorts: [],
    hasContainers: false,
    webServers: [],
    runtimes: [],
  };
  if (!scan || !scan.ok) return empty;
  const pathSet = new Set(selectedPaths);

  // Auto-include every detected engine (dump passwordlessly via root local auth).
  const dbEngines = [...new Set((scan.engines ?? []).filter((e) => e.present).map((e) => e.engine))].filter(
    (e): e is "mysql" | "postgres" => e === "mysql" || e === "postgres"
  );

  const containers = scan.containers ?? [];
  // Named Docker volumes = container mounts that are NOT absolute host paths.
  const dockerVolumes = [
    ...new Set(
      containers.flatMap((c) => c.mounts ?? []).filter((m) => !isCopyableAbsPath(m) && VOLNAME_RE.test(m))
    ),
  ].slice(0, 60);

  // Compose project dirs among the app dirs the customer is actually copying.
  const composeDirs = [
    ...new Set((scan.appDirs ?? []).filter((a) => a.signature === "compose" && pathSet.has(a.path)).map((a) => a.path)),
  ].slice(0, 40);

  const verifyPorts = [
    ...new Set((scan.ports ?? []).map((p) => p.port).filter((p) => Number.isInteger(p) && p >= 1 && p <= 65535 && p !== 22)),
  ].slice(0, 60);

  const hasContainers = containers.length > 0 || composeDirs.length > 0 || dockerVolumes.length > 0;

  // Web servers: match the owning process/service names, else default to nginx
  // when web roots exist (the overwhelmingly common case).
  const procBlob = [
    ...(scan.ports ?? []).map((p) => p.proc || ""),
    ...(scan.services ?? []).map((s) => s.name || ""),
  ]
    .join(" ")
    .toLowerCase();
  const webServers: ("nginx" | "apache")[] = [];
  if (/nginx/.test(procBlob)) webServers.push("nginx");
  if (/apache|httpd/.test(procBlob)) webServers.push("apache");
  if (webServers.length === 0 && (scan.webRoots ?? []).length > 0) webServers.push("nginx");

  // Runtimes: from running-app runtimes and listening-port owners. Conservative.
  const runtimeBlob = [
    ...(scan.appDirs ?? []).map((a) => a.runtime || ""),
    ...(scan.ports ?? []).map((p) => p.proc || ""),
  ]
    .join(" ")
    .toLowerCase();
  const runtimes: ("nodejs" | "python3")[] = [];
  if (/node|next|pm2/.test(runtimeBlob)) runtimes.push("nodejs");
  if (/python|gunicorn|uvicorn|celery/.test(runtimeBlob)) runtimes.push("python3");

  return { dbEngines, dockerVolumes, composeDirs, verifyPorts, hasContainers, webServers, runtimes };
}

